Here's a simple **command-line todo app** written in Python. It allows you to:  - Add a new todo. - Mark a todo as completed. - View all todos. - Incomplete todos are marked with **natural numbers** (1, 2, 3, ...). - Completed todos are marked with **prime numbers** (2, 3, 5, 7, ...).  ---  ### ✅ Features: - Add a todo. - Mark a todo as completed. - View todos with appropriate numbering. - Uses a simple file to persist todos (e.g., `todos.txt`).  ---  ### 📜 `todo_app.py`  ```python import os import sys import math  # File to store todos TODO_FILE = "todos.txt"  # Helper: Generate next natural number def next_natural():     if not os.path.exists(TODO_FILE):         return 1     with open(TODO_FILE, 'r') as f:         lines = f.readlines()         if not lines:             return 1         last_id = int(lines[-1].split(":")[0])         return last_id + 1  # Helper: Generate next prime number def next_prime():     def is_prime(n):         if n < 2:             return False         for i in range(2, int(math.sqrt(n)) + 1):             if n % i == 0:                 return False         return True      if not os.path.exists(TODO_FILE):         return 2     with open(TODO_FILE, 'r') as f:         lines = f.readlines()         if not lines:             return 2         last_id = int(lines[-1].split(":")[0])         n = last_id + 1         while True:             if is_prime(n):                 return n             n += 1  # Helper: List all todos def list_todos():     if not os.path.exists(TODO_FILE):         print("No todos found.")         return      with open(TODO_FILE, 'r') as f:         todos = f.readlines()      print("
Your Todos:")     for todo in todos:         parts = todo.strip().split(":")         if len(parts) < 2:             continue         id, content = parts[0], parts[1]         if id.isdigit():             print(f"{id}: {content}")         else:             print(f"{id}: {content}")  # Main function def main():     while True:         print("
Todo App")         print("1. Add Todo")         print("2. Mark Todo as Completed")         print("3. View Todos")         print("4. Exit")         choice = input("Choose an option: ")          if choice == "1":             todo = input("Enter your todo: ")             if not todo.strip():                 print("Todo cannot be empty.")                 continue             natural = next_natural()             with open(TODO_FILE, 'a') as f:                 f.write(f"{natural}:{todo}
")             print(f"Todo added with ID: {natural}")          elif choice == "2":             list_todos()             try:                 todo_id = int(input("Enter the ID of the todo to mark as completed: "))                 with open(TODO_FILE, 'r') as f:                     todos = f.readlines()                 found = False                 for i, line in enumerate(todos):                     parts = line.strip().split(":")                     if parts[0] == str(todo_id):                         found = True                         prime = next_prime()                         todos[i] = f"{prime}:{parts[1]}
"                         break                 if found:                     with open(TODO_FILE, 'w') as f:                         f.writelines(todos)                     print(f"Todo {todo_id} marked as completed with ID: {prime}")                 else:                     print("Todo not found.")             except ValueError:                 print("Invalid input. Please enter a number.")          elif choice == "3":             list_todos()          elif choice == "4":             print("Exiting...")             break          else:             print("Invalid choice. Please try again.")  if __name__ == "__main__":     main() ```  ---  ### 📝 How to Use:  1. Save the code in a file named `todo_app.py`. 2. Run it using Python:    ```bash    python todo_app.py    ``` 3. Choose options to add, complete, or view todos.  ---  ### 📌 Notes: - Todos are stored in a file called `todos.txt`. - Incomplete todos are numbered with natural numbers (1, 2, 3, ...). - Completed todos are numbered with prime numbers (2, 3, 5, 7, ...). - The app will automatically generate the next natural or prime number based on the last one used.  Let me know if you'd like to add features like deleting todos or saving to a database!

